package profilemedia

import (
	"encoding/base64"
	"testing"
)

// This is a synthetic 64x64, one-frame H.264 MP4 produced by ffmpeg.
const playableMP4Base64 = ""

func TestMP4ValidationRequiresPlayableContainerStructure(t *testing.T) {
	playable, err := base64.StdEncoding.DecodeString(playableMP4Base64)
	if err != nil {
		t.Fatal(err)
	}
	if !validMP4(playable, "video/mp4") {
		t.Fatal("rejected a decodable H.264 MP4")
	}
	if validMP4(playable, "image/jpeg") {
		t.Fatal("accepted a mislabeled MP4")
	}
	if validMP4([]byte("\x00\x00\x00\x18ftypisom\x00\x00\x00\x00isom"), "video/mp4") {
		t.Fatal("accepted an ftyp-only file with no video samples")
	}
	if validMP4(playable[:len(playable)-1], "video/mp4") {
		t.Fatal("accepted a truncated video sample")
	}
}
